import pickle

# Flask app with persistent machine learning model using pickled files
app = Flask(__name__)

@app.route('/', methods=['GET', 'POST'])
def index():
    # Need to handle both GET requests for form display and POST requests for processing prediction results
    if request.method == 'POST':
        # Deserialize the pickled RandomForestClassifier object from pickle file for reuse across requests
        model = pickle.load(open('model.pkl', 'rb'))

        # Extract numeric feature values from form submission
        feature1 = float(request.form['n'])

        # Single feature predicts across entire dataset
        prediction = model.predict([feature1])[0]

        # Return result to index template for immediate user feedback without redirect
        return render_template('index.html', result=prediction)

    else:
        # Return empty form on GET request
        return render_template('index.html')

# Flask development server runnable by default
if __name__ == '__main__':
    app.run()

